fn is_non_prime(n: u64) -> bool {
    // We assume n >= 2.
    // A non-prime (composite) number has a divisor k with 2 <= k < n.
    // It's enough to search for k up to sqrt(n), i.e., k * k <= n.
    // To avoid overflow in k*k, we rewrite that as k <= n / k.
    let mut k: u64 = 2;
    while k <= n / k {
        if n % k == 0 {
            return true;
        }
        k += 1;
    }
    false
}

